message.content:
{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile standing on a small patch of ground. Its entire body except for the back and forehead is covered in dense, long, shaggy brown fur that is darker on the lower legs and lighter tan on the chest and flank. The head is broad and bear-like with a lighter muzzle and dark nose. A single long, dark, ridged, glossy horn curves up from the center of the forehead. The dorsal side from the shoulders to the rump is covered by a large, highly glossy, dark reddish-brown to black segmented exoskeleton that sits on top of the fur, with a spiked shield over the shoulders and a domed, overlapping segmented section extending rearward. It stands on four thick furred limbs ending in clawed paws and has a very small rounded tail at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad bear-like head with dense brown fur, lighter tan fur around the muzzle and cheeks, a large dark brown-black nose at the tip, small brown eyes, and a closed mouth",
      "where": "at the front right of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "single long, glossy, dark brown to black horn with transverse ridges, tapering to a sharp point and curving upward and backward",
      "where": "rising from the center of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, fur-covered ears with the same shaggy brown fur as the head",
      "where": "on top of the head, one on each side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred, columnar legs covered in long shaggy brown fur, lighter on the inner flank and chest",
      "where": "two under the front chest and two under the rear rump, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with long dark claws visible at the tips, furred to the toes",
      "where": "at the bottom ends of the four legs, planted on the ground"
    },
    {
      "part": "tail",
      "looks_like": "very small, short, rounded nub covered in short brown fur",
      "where": "at the extreme left rear of the body, just below the rear edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "large, highly glossy, smooth, dark reddish-brown to black exoskeleton with a reflective surface, appearing hard and beetle-like",
      "where": "covering the entire dorsal side from just behind the neck over the shoulders to above the hind legs, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "an anterior shield with two pointed horn-like projections over the shoulders and a posterior dome of 7 to 8 overlapping transverse segments with a lower lateral flap bearing a row of oval openings",
      "where": "forming the shell on the back, the shield at the front over the shoulders and the segmented dome extending rearward to the rump"
    },
    {
      "part": "markings",
      "looks_like": "dense long shaggy fur, predominantly medium to dark brown with lighter tan on the chest, side and around the muzzle, no spots or stripes, fur texture is long and unkempt",
      "where": "covering the head, neck, torso, legs and tail, everywhere except the shell, horn, nose and claws"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
